using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_FirstPage_ReturnsCorrectItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.Equal(1, result[0]);
            Assert.Equal(10, result[9]);
        }

        [Fact]
        public void Create_SecondPage_ReturnsCorrectItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(11, result[0]);
            Assert.Equal(20, result[9]);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 3, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(3, result.PageIndex);
            Assert.Equal(21, result[0]);
            Assert.Equal(25, result[4]);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Empty(result);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Create_SinglePage_ReturnsAllItems()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(1, result.TotalPages);
        }

        [Fact]
        public void Create_ExactlyOnePage_TotalPagesIsOne()
        {
            var source = Enumerable.Range(1, 10).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.TotalPages);
        }

        [Fact]
        public void HasPreviousPage_OnFirstPage_ReturnsFalse()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_OnSecondPage_ReturnsTrue()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_OnFirstPageWithMultiplePages_ReturnsTrue()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_OnLastPage_ReturnsFalse()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 3, 10);

            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_SinglePage_ReturnsFalse()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void HasPreviousPage_SinglePage_ReturnsFalse()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.False(result.HasPreviousPage);
        }

        [Theory]
        [InlineData(1, 5, 4)]  // 17 items, pageSize 5 -> 4 pages
        [InlineData(2, 5, 4)]
        [InlineData(4, 5, 4)]  // last page with 2 items
        public void Create_VariousPageSizes_CalculatesCorrectTotalPages(int pageIndex, int pageSize, int expectedTotalPages)
        {
            var source = Enumerable.Range(1, 17).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex, pageSize);

            Assert.Equal(expectedTotalPages, result.TotalPages);
            Assert.Equal(pageIndex, result.PageIndex);
        }

        [Fact]
        public void Create_PageSize1_EachPageHasOneItem()
        {
            var source = new List<string> { "A", "B", "C" }.AsQueryable();

            var page1 = PaginatedList<string>.Create(source, 1, 1);
            var page2 = PaginatedList<string>.Create(source, 2, 1);
            var page3 = PaginatedList<string>.Create(source, 3, 1);

            Assert.Single(page1);
            Assert.Equal("A", page1[0]);
            Assert.Single(page2);
            Assert.Equal("B", page2[0]);
            Assert.Single(page3);
            Assert.Equal("C", page3[0]);
            Assert.Equal(3, page1.TotalPages);
        }

        [Fact]
        public void Constructor_SetsPropertiesCorrectly()
        {
            var items = new List<int> { 1, 2, 3 };

            var list = new PaginatedList<int>(items, 30, 2, 10);

            Assert.Equal(3, list.Count);
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(3, list.TotalPages); // ceil(30/10) = 3
            Assert.True(list.HasPreviousPage);
            Assert.True(list.HasNextPage);
        }
    }
}

