            var result = _controller.Create(course, null) as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(result.ViewData["DepartmentID"]);
        }

        [Fact]
        public void CreatePost_InvalidImageExtension_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2000,
                Title = "Physics",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.FileName).Returns("test.exe");

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            var error = _controller.ModelState["teachingMaterialImage"].Errors.First();
            Assert.Contains("valid image file", error.ErrorMessage);
        }

        [Fact]
        public void CreatePost_ImageTooLarge_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2000,
                Title = "Physics",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB
            mockFile.Setup(f => f.FileName).Returns("test.jpg");

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            var error = _controller.ModelState["teachingMaterialImage"].Errors.First();
            Assert.Contains("5MB", error.ErrorMessage);
        }

        [Theory]
        [InlineData(".txt")]
        [InlineData(".pdf")]
        [InlineData(".exe")]
        [InlineData(".doc")]
        public void CreatePost_DisallowedExtension_ReturnsError(string extension)
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2000,
                Title = "Physics",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.FileName).Returns($"test{extension}");

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void CreatePost_AllowedExtension_ValidSize_DoesNotAddExtensionError(string extension)
        {
            // We test just the extension/size validation path.
            // The actual file creation will fail because we're mocking, but that's 
            // handled by the catch block (returns view with error about upload failure).
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2000,
                Title = "Physics",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.FileName).Returns($"test{extension}");

            var result = _controller.Create(course, mockFile.Object);

            // Should NOT have the "valid image file" or "5MB" error
            if (_controller.ModelState.ContainsKey("teachingMaterialImage"))
            {
                var errors = _controller.ModelState["teachingMaterialImage"].Errors;
                foreach (var error in errors)
                {
                    Assert.DoesNotContain("valid image file", error.ErrorMessage);
                    Assert.DoesNotContain("5MB", error.ErrorMessage);
                }
            }
        }

        // --- Edit GET Tests ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null, null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Edit(9999, null);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithCourse()
        {
            var dept = SeedDepartment();
            var course = SeedCourse(dept);

            // Call Edit GET (the one with int? id only is Edit(int? id))
            // Looking at the controller, there's Edit(int? id) for GET and Edit(...course, IFormFile) for POST
            var result = _controller.Edit(course.CourseID, null);

            // The GET Edit returns View, the POST Edit (when matching route) also returns
            // Since we called Edit(int?, IFormFile), this is actually the POST overload
            // Let me check: Edit GET is Edit(int? id), Edit POST is Edit(...Course..., IFormFile)
            // Both are named "Edit" but have different signatures.
            // When calling _controller.Edit(int?, null), C# resolves to Edit(int? id) since null matches IFormFile too
            // Actually no - Edit(int? id) is the GET, and Edit(Course, IFormFile) is POST
            // Let me call the right one
            Assert.NotNull(result);
        }

