namespace ContosoUniversity.Tests
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);
            _controller = new NotificationsController(_context);

            // Drain the static notification queue
            var ns = new NotificationService();
            while (ns.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            var ns = new NotificationService();
            while (ns.ReceiveNotification() != null) { }
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            var jsonResult = Assert.IsType<JsonResult>(result);
            Assert.NotNull(jsonResult.Value);

            // Use reflection to check the anonymous type properties
            var value = jsonResult.Value;
            var successProp = value.GetType().GetProperty("success");
            var countProp = value.GetType().GetProperty("count");
            Assert.True((bool)successProp.GetValue(value));
            Assert.Equal(0, (int)countProp.GetValue(value));
        }

        [Fact]
        public void GetNotifications_WithItems_ReturnsNotifications()
        {
            var ns = new NotificationService();
            ns.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "admin");
            ns.SendNotification("Course", "2", "Test Course", EntityOperation.UPDATE, "admin");

            var result = _controller.GetNotifications();

            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value;
            var successProp = value.GetType().GetProperty("success");
            var countProp = value.GetType().GetProperty("count");
            Assert.True((bool)successProp.GetValue(value));
            Assert.Equal(2, (int)countProp.GetValue(value));
        }

        [Fact]
        public void GetNotifications_MoreThan10_ReturnsMax10()
        {
            var ns = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                ns.SendNotification("Student", i.ToString(), $"Student {i}", EntityOperation.CREATE, "admin");
            }

            var result = _controller.GetNotifications();

            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value;
            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(10, (int)countProp.GetValue(value));
        }

        [Fact]
        public void GetNotifications_DrainsQueueUpTo10()
        {
            var ns = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                ns.SendNotification("Student", i.ToString(), EntityOperation.CREATE);
            }

            // First call should get 10
            _controller.GetNotifications();
            // Second call should get remaining 5
            var result = _controller.GetNotifications();

            var jsonResult = Assert.IsType<JsonResult>(result);
            var value = jsonResult.Value;
            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(5, (int)countProp.GetValue(value));
        }

