[Fact]
public void CreatePost_ImageExactly5MB_DoesNotAddSizeError()
{
    var dept = SeedDepartment();
    var course = new Course
    {
        CourseID = 2000,
        Title = "Physics",
        Credits = 3,
        DepartmentID = dept.DepartmentID
    };

    var mockFile = new Mock<IFormFile>();
    mockFile.Setup(f => f.Length).Returns(5 * 1024 * 1024); // Exactly 5MB - boundary
    mockFile.Setup(f => f.FileName).Returns("test.jpg");

    var result = _controller.Create(course, mockFile.Object);

    // Should NOT have the 5MB size error (5MB is allowed, only > 5MB is rejected)
    if (_controller.ModelState.ContainsKey("teachingMaterialImage"))
    {
        var errors = _controller.ModelState["teachingMaterialImage"].Errors;
        foreach (var error in errors)
        {
            Assert.DoesNotContain("5MB", error.ErrorMessage);
        }
    }
}

