11.         public void Create_FirstPage_ReturnsCorrectItems()
12.         {
13.             // Arrange
14.             var source = Enumerable.Range(1, 25).AsQueryable();
15. 
16.             // Act
17.             var result = PaginatedList<int>.Create(source, 1, 10);
18. 
19.             // Assert
20.             Assert.Equal(10, result.Count);
21.             Assert.Equal(1, result.PageIndex);
22.             Assert.Equal(3, result.TotalPages);
